entries[24000] = { ["name"] = "Formel: Armschiene - Überragende Heilung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (325)\nBenötigt Thrallmar\n- Freundlich\nBenutzen: Lehrt Euch, Armschienen dauerhaft so zu verzaubern, dass sie den Effekt von Heilzaubern um 30 und Schadenszaubern um bis zu 10 erhöhen.\nArmschienen dauerhaft so verzaubern, dass sie den Effekt von Heilzaubern um bis zu 30 und Schadenszaubern um bis zu 10 erhöhen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[24001] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (330)\nBenötigt Thrallmar\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nVerkaufspreis:\nElixier der erheblichen Beweglichkeit\nBenötigt Stufe 55\nBenutzen: Erhöht 1 Stunde lang Eure Beweglichkeit um 35 und Eure kritische Trefferwertung um 20. Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen , Teufelsgras (2), Magieerfüllte Phiole" }
entries[24002] = { ["name"] = "Pläne: Teufelsstahlschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (360)\nBenötigt Thrallmar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschildstachels.\nVerkaufspreis:\nTeufelsstahlschildstachel\nBenutzen: Bringt einen Teufelsstahlstachel an Eurem Schild an, der bei jedem Blocken 26-38 Schaden verursacht.\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (4), Urfeuer (4), Urerde (4)" }
entries[24003] = { ["name"] = "Formel: Brust - Außergewöhnliche Werte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (345)\nBenötigt Thrallmar\n- Respektvoll\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft so zu verzaubern, dass sie alle Werte um 6 erhöhen.\nEine Brustrüstung dauerhaft so verzaubern, dass sie alle Werte um 6 erhöht. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
