entries[24158] = { ["name"] = "Vorlage: Khoriumband der Schatten", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (350)\nBenutzen: Lehrt Euch die Herstellung eines Khoriumbands der Schatten.\nVerkaufspreis:\nKhoriumband der Schatten\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nFinger\n+27 Ausdauer\nBenötigt Stufe 69\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 27.\nAnlegen: Stellt alle 5 Sek. 7 Mana wieder her.\nVerkaufspreis:\nBenötigt Khoriumbarren (2), Quecksilberadamantit (3), Urschatten (3)" }
