entries[24166] = { ["name"] = "Vorlage: Dicke Teufelsstahlhalskette", ["text"] = "Benötigt Juwelenschleifen (355)\nBenutzen: Lehrt Euch die Herstellung einer dicken Teufelsstahlhalskette\nVerkaufspreis:\nDicke Teufelsstahlhalskette\nWird beim Anlegen gebunden\nHals\n+36 Ausdauer\nBenötigt Stufe 70\nAnlegen: Erhöht Eure Abhärtungswertung um 23.\nBenutzen: Erhöht die Ausdauer naher Gruppenmitglieder 30 Min. lang um 20. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Quecksilberadamantit (3)" }
entries[24167] = { ["name"] = "Vorlage: Lebendiger Rubinanhänger", ["text"] = "Benötigt Juwelenschleifen (355)\nBenutzen: Lehrt Euch die Herstellung eines lebendigen Rubinanhängers.\nVerkaufspreis:\nLebendiger Rubinanhänger\nWird beim Anlegen gebunden\nHals\n+24 Ausdauer\n+15 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 35 und den verursachten Schaden um bis zu 12.\nAnlegen: Stellt alle 5 Sek. 6 Mana wieder her.\nBenutzen: Stellt 30 Min. lang jede Sekunde 6 Gesundheit bei allen in der Nähe befindlichen Gruppenmitgliedern wieder her. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Khoriumbarren (4), Quecksilberadamantit , Lebendiger Rubin" }
entries[24168] = { ["name"] = "Vorlage: Geflochtene Eterniumkette", ["text"] = "Benötigt Juwelenschleifen (360)\nBenutzen: Lehrt Euch die Herstellung einer geflochtenen Eterniumkette.\nVerkaufspreis:\nGeflochtene Eterniumkette\nWird beim Anlegen gebunden\nHals\nBenötigt Stufe 70\nAnlegen: Erhöht die Trefferwertung um 21.\nAnlegen: +5 Waffenschaden.\nBenutzen: Erhöht die kritische Trefferwertung naher Gruppenmitglieder 30 Min. lang um 28. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Eterniumbarren (2), Quecksilberadamantit (3)" }
entries[24169] = { ["name"] = "Vorlage: Auge der Nacht", ["text"] = "Benötigt Juwelenschleifen (360)\nBenutzen: Lehrt Euch die Herstellung eines Auges der Nacht.\nVerkaufspreis:\nAuge der Nacht\nWird beim Anlegen gebunden\nHals\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubertrefferwertung um 16.\nAnlegen: Erhöht die kritische Zaubertrefferwertung um 26.\nAnlegen: Erhöht Eure Zauberdurchschlagskraft um 15.\nBenutzen: Erhöht den Zauberschaden aller in der Nähe befindlichen Gruppenmitglieder 30 Min. lang um bis zu 34. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Gehärteter Adamantitbarren (2), Quecksilberadamantit (2), Nachtauge" }
entries[24170] = { ["name"] = "Vorlage: Zärtliche Morgenröte", ["text"] = "Benötigt Juwelenschleifen (365)\nBenutzen: Lehrt Euch die Herstellung einer zärtlichen Morgenröte.\nVerkaufspreis:\nZärtliche Morgenröte\nWird beim Anlegen gebunden\nHals\n+27 Ausdauer\n+19 Intelligenz\nBenötigt Stufe 70\nAnlegen: Stellt alle 5 Sek. 7 Mana wieder her.\nBenutzen: Alle Werte naher Gruppenmitglieder werden 30 Min. lang um 10 erhöht. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Eterniumbarren (2), Quecksilberadamantit (4), Golddraenit (2)" }
entries[24171] = { ["name"] = "Vorlage: Kette der Nebeleule", ["text"] = "Benötigt Juwelenschleifen (365)\nBenutzen: Lehrt Euch die Herstellung einer Kette der Nebeleule.\nVerkaufspreis:\nKette der Nebeleule\nWird beim Anlegen gebunden\nHals\n+19 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht die Verteidigungswertung um 18.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 21.\nBenutzen: Erhöht die Chance auf einen kritischen Zaubertreffer für nahe Gruppenmitglieder 30 Min. lang um 2%. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Khoriumbarren (2), Quecksilberadamantit (4), Azurmondstein (2)" }
entries[24172] = { ["name"] = "Vorlage: Kronenreif der grünen Flamme", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (370)\nBenutzen: Lehrt Euch die Herstellung eines Kronenreifs der grünen Flamme.\nVerkaufspreis:\nKronenreif der grünen Flamme\nWird beim Anlegen gebunden\nKopf Stoff\n138 Rüstung\n+36 Ausdauer\n+40 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Stufe 70\nAnlegen: Chance bei erfolgreichem Zauberwirken im Verlauf von 10 Sek. 90 Mana wiederherzustellen. (Procchance: 75%, 25s Abklingzeit)\nVerkaufspreis:\nBenötigt Khoriumbarren (20), Urleben (20), Talasit (2), Quecksilberadamantit (5)" }
entries[24173] = { ["name"] = "Vorlage: Reif der arkanen Macht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (370)\nBenutzen: Lehrt Euch die Herstellung eines Reifs der arkanen Macht.\nVerkaufspreis:\nReif der arkanen Macht\nWird beim Anlegen gebunden\nKopf Stoff\n138 Rüstung\n+39 Ausdauer\n+27 Intelligenz\n+27 Willenskraft\nHaltbarkeit 60 / 60\nBenötigt Stufe 70\nAnlegen: Chance von 2%, bei erfolgreichem Zauberwirken den Zauberschaden 15 Sek. lang um bis zu 120 zu erhöhen. (Procchance: 2%)\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (20), Urmana (20), Stern der Elune (2), Quecksilberadamantit (5)" }
entries[24174] = { ["name"] = "Vorlage: Anhänger der Eisflamme", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (360)\nBenötigt Hüter der Zeit\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Anhängers der Eisflamme.\nVerkaufspreis:\nAnhänger der Eisflamme\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Feuerwiderstand\nBenötigt Stufe 70\nBenutzen: Absorbiert 900 bis 2700 Feuerschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (2), Urwasser (6), Urfeuer (4), Quecksilberadamantit" }
