entries[24315] = { ["name"] = "Muster: Schweres Netherstoffnetz", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (325)\nBenötigt Expedition des Cenarius\n- Freundlich\nBenutzen: Lehrt Euch das Nähen eines schweren Netherstoffnetzes.\nVerkaufspreis:\nSchweres Netherstoffnetz\nBenötigt Schneiderei (325)\nBenutzen: Fängt ein bis zu 35 Meter entferntes Ziel 3 Sek. lang in einem Netz ein. Unzuverlässig gegen Ziele, die höher als Stufe 80 sind. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Netherstoff (6)" }
entries[24316] = { ["name"] = "Muster: Zauberstoff", ["text"] = "Benötigt Schneiderei (350)\nBenutzen: Lehrt Euch das Nähen von Zauberstoff\nDie Umwandlung dieser Gegenstände in Zauberstoff ist nur innerhalb des Nethersturms möglich, und die Energien des Nethersturms können nur in bestimmten Zeitabständen auf diese Art genutzt werden. Auf diese Art Energie zu entziehen wird den Zorn des Nethersturms auf Euch lenken.\nVerkaufspreis:\nZauberstoff\nVerkaufspreis:\nBenötigt Magieerfüllter Netherstoffballen , Urmana , Urfeuer" }
